import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十五章","description":"《正易心法》第二十五章——中爻之义，足为造化：以纳音与反切为喻，说明中爻（二三四五）是乾坤交错、造化化生的场所；参互成卦，故一卦具于四卦中，皆得祸福倚伏之象。","frontmatter":{"title":"正易心法·第二十五章","description":"《正易心法》第二十五章——中爻之义，足为造化：以纳音与反切为喻，说明中爻（二三四五）是乾坤交错、造化化生的场所；参互成卦，故一卦具于四卦中，皆得祸福倚伏之象。","category":"guide","aliases":["正易心法第二十五章","中爻之义足为造化","参互成卦"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-25.md","filePath":"yijing/zheng-yi-xin-fa/chapter-25.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-25.md"},k=r({...c,setup(u){const i=[{id:"z25-01",label:"一、中爻足为造化",showLabel:!0,sentences:[[{text:"中爻",glossary:"zhongyao"},"之义，足为",{text:"造化",glossary:"zaohua"},"。纳音为",{text:"切脚",glossary:"qiejiao"},"，其理则一。"]],note:["中爻的意义，足以成为造化的枢纽。纳音与反切注音，道理是同一个。（**「中爻」指二、三、四、五爻**——除初爻、上爻之外的四爻，也就是两个互体的取爻范围。**本章是第十九章「互卦」的进一步深化**：第十九章说一卦含八卦，本章说中爻就是那「造化之气」发生的地方。）"]},{id:"z25-02",label:"二、纳音之喻",showLabel:!0,sentences:[["纳音，甲为木，子为水，甲子交合则生金。"]],note:["纳音：甲属木，子属水，甲子两者交合，纳音则生金。（**两个已知元素交合，生出第三个新元素**——这是「造化」的最小模型：**两端相交，中间生新。** 甲子纳音为「海中金」，是六十甲子纳音的起首。）"]},{id:"z25-03",label:"三、切脚之喻",showLabel:!0,sentences:[["切脚，如德为父，红为母，德红反切即东字。"]],note:["反切：比如「德」为父（取声母），「红」为母（取韵母），德红反切，就拼出「东」字的读音。（**上字取声、下字取韵，两字合成一个新字**——与纳音、与卦画是同一个道理：**两端相合，生出第三者。**「切脚」即「反切」，古代的注音法。）"]},{id:"z25-04",label:"四、卦体亦然",showLabel:!0,sentences:[["卦体亦然。上体为乾，下体为坤，交错乃生六子，即中爻二三四五也。"]],note:["卦的结构也是如此：上体为乾、下体为坤，两者交错乃生六子——这就是中爻的二、三、四、五爻。（**第三个类比**：乾坤（父母）交合 → 六子（中爻）。**造化的本质是：阴阳（两端）交合，在中间生出新的存在。** 这与第九章「乾坤错杂，乃生六子」是同一件事，本章给出了它的普遍形式。）"]},{id:"z25-05",label:"五、参互成卦",showLabel:!0,sentences:[["二三四五，造化之气，",{text:"参互成卦",glossary:"canhuChengua"},"。"]],note:["二、三、四、五爻，是造化之气，相互交叉参合，组成新的卦象。（**从中爻取互卦**：上互取三、四、五爻，下互取二、三、四爻，两个互体合成一个新的六爻卦——这就是第十九章所说的「参卦」。**麻衣强调的不是机械推算，而是每一卦的内部都藏着别的卦。**）"]},{id:"z25-06",label:"六、祸福倚伏",showLabel:!0,sentences:[["如屯中有剥，蒙中有复，主此一卦每具于四卦中，皆得",{text:"祸福倚伏",glossary:"huofuYifu"},"之象。如屯、比、观、益中皆有剥，蒙、师、损中皆有复是也。"]],note:["比如屯卦中含有剥卦，蒙卦中含有复卦——这说明每一卦都具备于另外四卦之中，都能得到祸福倚伏的卦象。就像屯、比、观、益中都含有剥，蒙、师、损中都含有复。（**「祸福倚伏」语出《老子》「祸兮福所倚，福兮祸所伏」**——吉卦（益）中藏着凶卦（剥），凶卦（屯）中也藏着凶卦（剥）：**祸福从不单独存在，任何当下状态都同时包含着其他卦的潜在走向。**）"]}],o=[{id:"zhongyao",term:"中爻",pinyin:"zhōng yáo",meaning:"六爻卦中的二、三、四、五爻（除初、上之外的四爻），是造化之气的所在。"},{id:"zaohua",term:"造化",pinyin:"zào huà",meaning:"天地化生万物的功能。「足为造化」即足以成为造化的枢纽。"},{id:"qiejiao",term:"切脚",pinyin:"qiè jiǎo",meaning:"即「反切」，古代的注音法：取上字声母、下字韵母拼合成新字的读音。"},{id:"canhuChengua",term:"参互成卦",pinyin:"cān hù chéng guà",meaning:"中爻二三四五相互交叉参合，组成新的卦象（即互体与参卦）。"},{id:"huofuYifu",term:"祸福倚伏",pinyin:"huò fú yǐ fú",meaning:"祸福相互依存、隐伏。语出《老子》「祸兮福所倚，福兮祸所伏」。"}];return(b,n)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十五章" tabindex="-1">正易心法·第二十五章 <a class="header-anchor" href="#正易心法·第二十五章" aria-label="Permalink to &quot;正易心法·第二十五章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章有两个层次的命题：</p><p><strong>第一层：三个类比，一个原理</strong></p><table tabindex="0"><thead><tr><th>例</th><th>两端</th><th>所生</th></tr></thead><tbody><tr><td><strong>纳音</strong></td><td>甲（木）＋子（水）</td><td>金</td></tr><tr><td><strong>反切</strong></td><td>德（声）＋红（韵）</td><td>东（音）</td></tr><tr><td><strong>卦体</strong></td><td>乾（上体）＋坤（下体）</td><td>六子（中爻）</td></tr></tbody></table><p><strong>统一原理</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两端（父母／上下）相交</span></span>
<span class="line"><span>→ 中间生出新的东西（子／音／卦）</span></span>
<span class="line"><span>= 造化的本质：阴阳交合，化生万物</span></span></code></pre></div><p><strong>第二层：参互成卦，故一卦具于四卦中</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中爻二三四五 → 取两个互体 → 参合为一个新卦</span></span>
<span class="line"><span>故每一卦都隐藏着其他卦的信息</span></span>
<span class="line"><span>如屯中有剥，蒙中有复</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「中爻」是什么？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>狭义：六爻卦中的二、三、四、五爻</span></span>
<span class="line"><span>广义：从这四爻中取出的两个互卦</span></span>
<span class="line"><span>     上互卦（三四五爻）</span></span>
<span class="line"><span>     下互卦（二三四爻）</span></span>
<span class="line"><span>     两个互卦合成一个新的六爻卦</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的用法：广义</span></span>
<span class="line"><span>  中爻不只是「中间的爻」，而是「造化之气的发生场所」</span></span></code></pre></div><p><strong>「足为造化」的深意</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只凭中爻（二三四五）的参互变化</span></span>
<span class="line"><span>就足以涵盖天地造化的全部信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>为什么？</span></span>
<span class="line"><span>  因为中爻是乾坤交合的产物</span></span>
<span class="line"><span>  = 乾坤（父母）的全部信息，都浓缩在中爻（子女）里</span></span>
<span class="line"><span>  = 从中爻可以读出整个宇宙的变化</span></span></code></pre></div><p><strong>「参互成卦」的位置</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十九章：一卦具八卦（正、伏、互、参）</span></span>
<span class="line"><span>第二十五章：中爻之义，足为造化（互与参的根据）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第十九章说「是什么」（一卦含八卦）</span></span>
<span class="line"><span>第二十五章说「为什么」（因为中爻是造化之气）</span></span></code></pre></div><p><strong>「祸福倚伏」的含义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>吉卦（益）中藏着凶卦（剥）</span></span>
<span class="line"><span>凶卦（屯）中也藏着凶卦（剥）</span></span>
<span class="line"><span>→ 祸福从不单独存在</span></span>
<span class="line"><span>→ 任何当下状态都同时包含着其他卦的潜在走向</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 《老子》「祸兮福所倚，福兮祸所伏」的卦象化</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把三个类比并列看：<strong>纳音、反切、卦体</strong>——<strong>两两相加，生出第三者</strong>；</li><li>再看「中爻」的范围：<strong>二三四五</strong>——除掉初、上；</li><li>最后读「祸福倚伏」——<strong>这是本章的落点，不只是技术。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>中爻</strong>：二三四五，造化之气所在。</li><li><strong>纳音</strong>：甲子交合生金（两端生新）。</li><li><strong>切脚</strong>：德红反切为东（两字生新）。</li><li><strong>卦体</strong>：乾坤交错生六子（两体生中爻）。</li><li><strong>参互成卦</strong>：中爻参合成卦。</li><li><strong>祸福倚伏</strong>：一卦具于四卦中。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,23)),e(l,{colophon:"中爻造化 · 纳音切脚 · 参互成卦 · 祸福倚伏",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十五章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。标题句「纳音为切脚」之「为」，据文义当读作「与／如」（纳音与反切），仍依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"中爻",pinyin:["zhōng","yáo"],meaning:"二、三、四、五爻（除初、上之外的四爻）——是造化之气的所在，互体与参卦的取爻范围。"},{term:"纳音",pinyin:["nà","yīn"],meaning:"甲（木）与子（水）交合而生金——两个已知元素交合，生出第三个新元素。"},{term:"切脚（反切）",pinyin:["qiè","jiǎo"],meaning:"「德」取声母、「红」取韵母，合成「东」——上字取声、下字取韵，两字生一新字。"},{term:"参互成卦",pinyin:["cān","hù"],meaning:"中爻二三四五相互交叉参合组成新卦。麻衣的重点不在机械推算，而在一卦内部藏着别的卦。"},{term:"祸福倚伏",pinyin:["huò","fú"],meaning:"《老子》「祸兮福所倚，福兮祸所伏」。屯中有剥、蒙中有复——祸福从不单独存在。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章有两个层次：<strong>三个类比一个原理</strong>（纳音、反切、卦体——两端相交，中间生新）；<strong>参互成卦</strong>（故一卦具于四卦中，皆得祸福倚伏之象）。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「足为造化」的深意</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只凭中爻（二三四五）的参互变化，就足以涵盖天地造化的全部信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>因为中爻是乾坤交合的产物</span></span>
<span class="line"><span>= 乾坤（父母）的全部信息，都浓缩在中爻（子女）里</span></span>
<span class="line"><span>= 从中爻可以读出整个宇宙的变化</span></span></code></pre></div><p><strong>「其理则一」的三者共性</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纳音：甲（木）× 子（水）= 金</span></span>
<span class="line"><span>反切：德（声）+ 红（韵）= 东</span></span>
<span class="line"><span>中爻：乾（上）+ 坤（下）= 六子</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不同领域（音韵学、五行学、易学）都在描述同一个宇宙原理：</span></span>
<span class="line"><span>阴阳（两端）交合，在中间生出新的存在</span></span></code></pre></div><p><strong>与第十九章的关系</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td>第十九章</td><td>一卦具八卦（正、伏、互、参）——「是什么」</td></tr><tr><td>第二十五章</td><td>中爻之义，足为造化——「为什么」</td></tr></tbody></table><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>先把三个类比并列看：<strong>两两相加，生出第三者</strong>；</li><li>再看「中爻」的范围：<strong>二三四五</strong>——除掉初、上；</li><li>最后读「祸福倚伏」：<strong>这是本章的落点，不只是技术。</strong></li><li>顺着钩子想（承接昇哥的问题）：<strong>如果吉卦里藏着凶、凶卦里藏着吉，那么占一卦，得到的是「当下的象」，还是「潜藏的象」？</strong> 我的看法：<strong>两者都是，而且不必分开。</strong> 麻衣没有说「趋吉避凶」，他说「祸福倚伏」——<strong>不是「吉凶可以选择」，而是「吉凶本来就同时在场」。</strong> 这已经不是占卜观的问题，是世界观的问题：<strong>「趋吉避凶」把吉凶当两个可选项；「祸福倚伏」把吉凶当一个东西的两面。</strong> 麻衣站后者。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>中爻的意义，足以成为造化的枢纽。纳音与反切注音，道理是同一个。</p><p>纳音：甲属木，子属水，甲子两者交合，纳音则生金。反切：比如「德」为父（取声母），「红」为母（取韵母），德红反切，就拼出「东」字的读音。</p><p>卦的结构也是如此：上体为乾、下体为坤，两者交错乃生六子——这就是中爻的二、三、四、五爻。</p><p>二、三、四、五爻，是造化之气，相互交叉参合，组成新的卦象。</p><p>比如屯卦中含有剥卦，蒙卦中含有复卦——这说明每一卦都具备于另外四卦之中，都能得到祸福倚伏的卦象。就像屯、比、观、益中都含有剥，蒙、师、损中都含有复。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十五章给「造化」下了一个可以看懂的定义——<strong>两头一交，中间就生出个新东西；卦是这样，字音是这样，五行也是这样。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>三个类比的分量</strong>——麻衣把<strong>纳音（五行）、反切（音韵）、卦画（易学）</strong> 并排放在一起，说「其理则一」。<strong>这不是类比，是同一个结构的三种显影。</strong></li><li><strong>「德红反切即东」</strong>——这个例子很妙。<strong>「德」提供声母，「红」提供韵母，两个都不是「东」，合起来就是「东」。</strong> 造化不是把两样东西拼在一起，<strong>是让两个都不是它的东西，生出一个新的。</strong></li><li><strong>「中爻」的范围</strong>——二三四五，<strong>把初、上留在外面</strong>。初是地、上是天，天地不动，中间四爻才是「气」活动的地方。<strong>这与我平时想事情的方式不一样：我总盯着两头（起点和终点），麻衣说，造化在中间。</strong></li><li><strong>「祸福倚伏」</strong>——这是本章真正的落点。<strong>吉卦里藏着凶，凶卦里也藏着凶。</strong> 麻衣说不必等到「变卦」才知道，<strong>当下这一卦里就有。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「祸福倚伏」与「趋吉避凶」，是同一件事吗？</strong> 我的看法：<strong>完全不同。</strong> 「趋吉避凶」把吉凶当成两个可以挑选的对象；<strong>「祸福倚伏」说它们本来就在一起，你选不了，只能看见。</strong> 麻衣的占卜观，因此不是「怎么避开凶」，而是「<strong>怎么看见此刻同时在场的东西</strong>」。这与第一章「知落处」是同一条线：<strong>看得见，才有资格谈吉凶。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 乾坤错杂生六子（本章的普遍形式）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-19">第十九章 · 凡具八卦</a> — 互卦与参卦（本章说明其根据）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-22">第二十二章 · 须求变复</a> — 变复（另一条读卦之路，与「参互」互补）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-26">第二十六章</a> — 余气（卦序的自然之理，与本章同属「自然」一线）</li></ul>`,24))])}}});export{y as __pageData,k as default};
